(2, 1781528447, 1781528447, 'new', 'skippedPaths', 25, '6fd0d290b978eab8027e6b79501ac149', '6fd0d290b978eab8027e6b79501ac149', '1 path was skipped for the malware scan due to scan settings', 'The option \"Scan files outside your WordPress installation\" is off by default, which means 1 path and its file(s) will not be scanned for malware or unauthorized changes. To continue skipping this path, you may ignore this issue. Or to start scanning it, enable the option and subsequent scans will include it. Some paths may not be necessary to scan, so this is optional. <a href=\"https://www.wordfence.com/help/?query=scan-result-skipped-paths\" target=\"_blank\" rel=\"noopener noreferrer\">Learn More<span class=\"screen-reader-text\"> (opens in new tab)</span></a><br><br>The path skipped is C:\\laragon\\www\\Portfolio-Web-Developer\\.git', 'a:0:{}'),
(3, 1781528588, 1781528588, 'new', 'wfPluginUpgrade', 50, '25d42c5656bfc1443a19492abc337c98', '25d42c5656bfc1443a19492abc337c98', 'The Plugin \"GDPR Cookie Compliance\" needs an upgrade (5.0.14 -> 5.0.15).', 'You need to upgrade \"GDPR Cookie Compliance\" to the newest version to ensure you have any security fixes the developer has released.', 'a:23:{s:22:\"Elementor tested up to\";s:0:\"\";s:26:\"Elementor Pro tested up to\";s:0:\"\";s:4:\"Name\";s:22:\"GDPR Cookie Compliance\";s:9:\"PluginURI\";s:53:\"https://wordpress.org/plugins/gdpr-cookie-compliance/\";s:7:\"Version\";s:6:\"5.0.14\";s:11:\"Description\";s:144:\"Our plugin is useful in preparing your site for the following data protection and privacy regulations: GDPR, CCPA, PIPEDA, AAP, LGPD and others.\";s:6:\"Author\";s:12:\"Moove Agency\";s:9:\"AuthorURI\";s:27:\"https://www.mooveagency.com\";s:10:\"TextDomain\";s:22:\"gdpr-cookie-compliance\";s:10:\"DomainPath\";s:10:\"/languages\";s:7:\"Network\";b:0;s:10:\"RequiresWP\";s:0:\"\";s:11:\"RequiresPHP\";s:0:\"\";s:9:\"UpdateURI\";s:0:\"\";s:15:\"RequiresPlugins\";s:0:\"\";s:5:\"Title\";s:22:\"GDPR Cookie Compliance\";s:10:\"AuthorName\";s:12:\"Moove Agency\";s:10:\"pluginFile\";s:95:\"C:/laragon/www/Portfolio-Web-Developer/wp-content/plugins/gdpr-cookie-compliance/moove-gdpr.php\";s:4:\"slug\";s:22:\"gdpr-cookie-compliance\";s:10:\"newVersion\";s:6:\"5.0.15\";s:5:\"wpURL\";s:52:\"https://wordpress.org/plugins/gdpr-cookie-compliance\";s:15:\"updateAvailable\";b:1;s:10:\"vulnerable\";b:0;}'),
(4, 1781528588, 1781528588, 'new', 'wfPluginUpgrade', 50, 'cd24710b3e3b8747e3e60ff83b3f2f0e', 'cd24710b3e3b8747e3e60ff83b3f2f0e', 'The Plugin \"Elementor Pro\" needs an upgrade (4.0.4 -> 4.1.1).', 'You need to upgrade \"Elementor Pro\" to the newest version to ensure you have any security fixes the developer has released.', 'a:23:{s:22:\"Elementor tested up to\";s:8:\"4.0.4-ga\";s:26:\"Elementor Pro tested up to\";s:0:\"\";s:4:\"Name\";s:13:\"Elementor Pro\";s:9:\"PluginURI\";s:55:\"https://go.elementor.com/wp-dash-wp-plugins-author-uri/\";s:7:\"Version\";s:5:\"4.0.4\";s:11:\"Description\";s:216:\"Elevate your designs and unlock the full power of the Atomic Editor. Gain access to dozens of Pro widgets, Website Templates, Theme Builder, Pop Ups, Forms, reusable Components, and WooCommerce building capabilities.\";s:6:\"Author\";s:13:\"Elementor.com\";s:9:\"AuthorURI\";s:55:\"https://go.elementor.com/wp-dash-wp-plugins-author-uri/\";s:10:\"TextDomain\";s:13:\"elementor-pro\";s:10:\"DomainPath\";s:0:\"\";s:7:\"Network\";b:0;s:10:\"RequiresWP\";s:3:\"6.7\";s:11:\"RequiresPHP\";s:3:\"7.4\";s:9:\"UpdateURI\";s:0:\"\";s:15:\"RequiresPlugins\";s:9:\"elementor\";s:5:\"Title\";s:13:\"Elementor Pro\";s:10:\"AuthorName\";s:13:\"Elementor.com\";s:10:\"pluginFile\";s:89:\"C:/laragon/www/Portfolio-Web-Developer/wp-content/plugins/elementor-pro/elementor-pro.php\";s:4:\"slug\";s:13:\"elementor-pro\";s:10:\"newVersion\";s:5:\"4.1.1\";s:5:\"wpURL\";s:35:\"https://elementor.com/pro/changelog\";s:15:\"updateAvailable\";b:1;s:10:\"vulnerable\";b:0;}');
